\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Dark Mode Color Theme ──
\definecolor{primary}{HTML}{1E293B}        % deep slate (background)
\definecolor{secondary}{HTML}{3B82F6}      % electric blue
\definecolor{accent}{HTML}{10B981}         % emerald green
\definecolor{accent2}{HTML}{F59E0B}        % amber
\definecolor{accent3}{HTML}{EF4444}        % red
\definecolor{bgposter}{HTML}{0F172A}       % near-black blue
\definecolor{cardbg}{HTML}{1E293B}         % card background
\definecolor{cardborder}{HTML}{334155}     % card border
\definecolor{textwhite}{HTML}{F8FAFC}      % primary text
\definecolor{textgray}{HTML}{94A3B8}       % secondary text
\definecolor{highlight}{HTML}{1E3A8A}      % highlight blue
\definecolor{starbg}{HTML}{1F2937}         % star count background

\pagecolor{bgposter}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{accent}$\blacktriangleright$}}

% ── Card styles ──
\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colback=cardbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=highlight,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top,
  },
  accentcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top,
  },
  ambercard/.style={
    enhanced, arc=4pt, boxrule=1pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent2},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent2},
    coltitle=accent2, colbacktitle=cardbg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent2!50},
    valign=top,
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=1pt, colback=highlight,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=highlight,
    toptitle=6pt, bottomtitle=6pt,
    valign=top,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══ HEADER ══
\posterbox[
  enhanced, colback=primary, colframe=cardborder, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=16pt, bottom=12pt,
  halign=center, valign=center,
]{name=header, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries\textwhite COding AI LEADERBOARD}\\[10pt]
  {\fontsize{32}{40}\selectfont\textgray Top GitHub Repos by Weekly Star Growth}\\[8pt]
  {\fontsize{28}{36}\selectfont\color{accent2} Week of April 9–15, 2026}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=cardbg, boxrule=1pt, arc=4pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center, borderline={1pt}{0pt}{cardborder},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent2}{starbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{accent2} +9,715}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textgray} hermes-agent}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Top Weekly Star Gain}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary}{starbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{secondary} 48k}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Total Stars}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Across Top 20}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent}{starbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{accent} 5}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Claude-Related}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Repos in Top 20}\vspace{6pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent3}{starbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{58}{72}\selectfont\bfseries\color{accent3} 10}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} Repos Gaining}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textwhite!70} 2k+ Stars}\vspace{6pt}%
    }}
  \end{minipage}
}

% ══ SECTION: TOP 5 HIGHLIGHT ══
\posterbox[
  accentcard, title={TOP 5 FASTEST-RISING}
]{name=top5, column=1, span=3, between=row6 and row10}{
  \fontsize{28}{36}\selectfont
  \begin{tabular}{p{0.06\linewidth}p{0.50\linewidth}p{0.20\linewidth}p{0.16\linewidth}}
    \rowcolor{accent2!20}
    \textbf{Rank} & \textbf{Repository} & \textbf{Stars} & \textbf{Trend} \\
    \rowcolor{cardbg}
    \textbf{1} & \color{accent2}\bfseries NousResearch/hermes-agent & \color{accent2}\bfseries +9,715 & \color{accent2}★ LEAD \\
    \rowcolor{accent2!10}
    \textbf{2} & forrestchang/andrej-karpathy-skills & +4,917 & \color{accent}{▲} \\
    \rowcolor{cardbg}
    \textbf{3} & JuliusBrussee/caveman & +4,407 & — \\
    \rowcolor{accent2!10}
    \textbf{4} & MemPalace/mempalace & +3,524 & \color{accent3}{▼} \\
    \rowcolor{cardbg}
    \textbf{5} & VoltAgent/awesome-design-md & +3,246 & — \\
  \end{tabular}
}

% ══ SECTION: THEMATIC CLUSTERS ══
\posterbox[
  darkcard, title={EMERGING THEMES}
]{name=themes, column=1, span=3, between=row10 and row13}{
  \fontsize{26}{34}\selectfont
  \begin{minipage}[t]{0.32\linewidth}\centering
    \colorbox{accent!20}{\parbox{0.94\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{24}{30}\selectfont\bfseries\color{accent} AGENT FRAMEWORKS}\\[6pt]
      {\fontsize{20}{26}\selectfont\color{textwhite} hermes-agent leads}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Open agent tooling}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} gaining major traction}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.32\linewidth}\centering
    \colorbox{secondary!20}{\parbox{0.94\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{24}{30}\selectfont\bfseries\color{secondary} CLAUDE CODE ECOSYSTEM}\\[6pt]
      {\fontsize{20}{26}\selectfont\color{textwhite} 5 repos, 8,500+ stars}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} best-practices, memory,}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} extensions, wrappers}\vspace{4pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.32\linewidth}\centering
    \colorbox{accent2!20}{\parbox{0.94\linewidth}{%
      \centering\vspace{4pt}%
      {\fontsize{24}{30}\selectfont\bfseries\color{accent2} UTILITY \& INFRA}\\[6pt]
      {\fontsize{20}{26}\selectfont\color{textwhite} markitdown, design-md}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Foundation tools}\\[4pt]
      {\fontsize{18}{24}\selectfont\color{textgray} sustaining interest}\vspace{4pt}%
    }}
  \end{minipage}
}

% ══ SECTION: FULL RANKING TABLE ══
\posterbox[
  highlightcard, title={FULL WEEKLY TOP 20 RANKING}
]{name=ranking, column=1, span=3, between=row13 and row19}{
  \fontsize{24}{32}\selectfont
  \rowcolors{1}{cardbg}{starbg}
  \begin{tabular}{p{0.06\linewidth}p{0.52\linewidth}p{0.18\linewidth}p{0.14\linewidth}p{0.06\linewidth}}
    \rowcolor{highlight}
    \textbf{Rank} & \textbf{Repository} & \textbf{Stars} & \textbf{Category} & \textbf{Move} \\
    \textbf{1} & \color{accent2}\bfseries NousResearch/hermes-agent & \color{accent2}+9,715 & agent & — \\
    \textbf{2} & forrestchang/andrej-karpathy-skills & +4,917 & utility & \color{accent}{▲} \\
    \textbf{3} & JuliusBrussee/caveman & +4,407 & tool & — \\
    \textbf{4} & MemPalace/mempalace & +3,524 & utility & \color{accent3}{▼} \\
    \textbf{5} & VoltAgent/awesome-design-md & +3,246 & design & — \\
    \textbf{6} & microsoft/markitdown & +3,048 & utility & \color{accent}{▲} \\
    \textbf{7} & safishamsi/graphify & +2,763 & design & \color{accent3}{▼} \\
    \textbf{8} & obra/superpowers & +2,180 & tool & \color{accent}{▲} \\
    \textbf{9} & shanraisshan/claude-code-best-practice & +2,151 & claude & \color{accent}{▲} \\
    \textbf{10} & affaan-m/everything-claude-code & +1,978 & claude & — \\
    \textbf{11} & thedotmack/claude-mem & +1,828 & claude & \color{accent}{▲} \\
    \textbf{12} & santifer/career-ops & +1,788 & tool & \color{accent3}{▼} \\
    \textbf{13} & multica-ai/multica & +1,506 & tool & \color{accent}{▲} \\
    \textbf{14} & shiyu-coder/Kronos & +1,286 & tool & \color{accent}{▲} \\
    \textbf{15} & ultraworkers/claw-code & +1,285 & claude & \color{accent3}{▼} \\
    \textbf{16} & openclaw/openclaw & +1,268 & claude & \color{accent3}{▼} \\
    \textbf{17} & OpenBMB/VoxCPM & +1,266 & agent & \color{accent3}{▼} \\
    \textbf{18} & addyosmani/agent-skills & +1,195 & agent & \color{accent3}{▼} \\
    \textbf{19} & rtk-ai/rtk & +1,098 & tool & — \\
    \textbf{20} & garrytan/gstack & +1,012 & tool & \color{accent2}{N} \\
  \end{tabular}
}

% ══ KEY TAKEAWAYS ══
\posterbox[
  ambercard, title={KEY TAKEAWAYS}
]{name=takeaways, column=1, span=3, between=row19 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{minipage}[t]{0.30\linewidth}\centering
    {\fontsize{40}{50}\selectfont\bfseries\color{accent} 1}\\[6pt]
    {\fontsize{22}{28}\selectfont\color{textwhite} Agent-first development}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} is surging}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textgray} hermes-agent's +9,715 stars}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textgray} dwarfs every other entry}\\
  \end{minipage}\hfill
  \begin{minipage}[t]{0.30\linewidth}\centering
    {\fontsize{40}{50}\selectfont\bfseries\color{secondary} 2}\\[6pt]
    {\fontsize{22}{28}\selectfont\color{textwhite} Claude Code ecosystem}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} is expanding fast}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textgray} 25\% of top 20 repos orbit}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textgray} a single product}\\
  \end{minipage}\hfill
  \begin{minipage}[t]{0.30\linewidth}\centering
    {\fontsize{40}{50}\selectfont\bfseries\color{accent2} 3}\\[6pt]
    {\fontsize{22}{28}\selectfont\color{textwhite} Utility tools like}\\[4pt]
    {\fontsize{20}{26}\selectfont\color{textgray} markitdown show}\\[6pt]
    {\fontsize{18}{24}\selectfont\color{textgray} foundational open-source}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textgray} sustaining strong interest}\\
  \end{minipage}
}

\end{tcbposter}
\end{document}

